import React, { useState, useEffect, useRef } from 'react';

/* ─────────────────────────────────────────────────────────────────────────
   JourneyRoadmap — "The Roads I Took"
   A branching-path story component showing life exploration during 2014-2017.
   ───────────────────────────────────────────────────────────────────────── */

const STYLES = `
  .jr-root {
    position: relative;
    padding: 0;
    overflow: hidden;
  }

  /* ── Ambient light blobs ── */
  .jr-root::before {
    content: '';
    position: absolute; inset: 0;
    background:
      radial-gradient(ellipse 50% 40% at 15% 20%, rgba(124,58,237,0.06) 0%, transparent 100%),
      radial-gradient(ellipse 40% 50% at 85% 70%, rgba(16,185,129,0.05) 0%, transparent 100%),
      radial-gradient(ellipse 60% 30% at 50% 0%, rgba(245,158,11,0.04) 0%, transparent 100%);
    pointer-events: none;
  }

  /* ── Chapter system ── */
  .jr-chapter {
    position: relative;
    padding: 28px 32px 28px;
    border-bottom: 1px solid rgba(255,255,255,0.03);
    opacity: 0;
    transform: translateY(16px);
    transition: opacity 1s cubic-bezier(0.22,1,0.36,1),
                transform 1s cubic-bezier(0.22,1,0.36,1);
  }
  .jr-chapter.active {
    opacity: 1;
    transform: translateY(0);
  }
  .jr-chapter:last-child {
    border-bottom: none;
    padding-bottom: 24px;
  }

  /* Chapter number */
  .jr-ch-num {
    display: inline-flex; align-items: center; gap: 7px;
    font-family: var(--mono-font);
    font-size: 0.62rem; font-weight: 600;
    letter-spacing: 0.14em; text-transform: uppercase;
    margin-bottom: 14px;
    opacity: 0.4;
  }
  .jr-ch-num-dot {
    width: 6px; height: 6px; border-radius: 50%;
    box-shadow: 0 0 8px currentColor;
  }

  /* Chapter title */
  .jr-ch-title {
    font-family: var(--heading-font);
    font-size: 1.2rem; font-weight: 800;
    color: var(--pearl);
    margin-bottom: 8px;
    line-height: 1.3;
    letter-spacing: -0.01em;
  }
  .jr-ch-subtitle {
    font-size: 0.84rem; color: rgba(148,163,184,0.85);
    line-height: 1.7; max-width: 540px;
    margin-bottom: 20px;
  }

  /* ── Fork visual ── */
  .jr-fork-wrap {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 44px 1fr;
    gap: 0;
    margin: 4px 0 4px;
  }
  @media (max-width: 600px) {
    .jr-fork-wrap {
      grid-template-columns: 1fr;
      gap: 14px;
    }
    .jr-fork-divider { display: none; }
  }

  /* Fork card — glass style */
  .jr-fork-card {
    padding: 22px;
    border-radius: 16px;
    border: 1px solid rgba(255,255,255,0.06);
    background: rgba(255,255,255,0.02);
    backdrop-filter: blur(8px);
    position: relative;
    overflow: hidden;
    transition: all 0.5s cubic-bezier(0.22,1,0.36,1);
    opacity: 0;
    transform: scale(0.96) translateY(6px);
  }
  .jr-fork-card.active {
    opacity: 1;
    transform: scale(1) translateY(0);
  }

  /* Top accent line */
  .jr-fork-card::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0;
    height: 2px;
    border-radius: 2px 2px 0 0;
    opacity: 0.7;
  }

  /* Inner glow */
  .jr-fork-card::after {
    content: '';
    position: absolute; inset: 0;
    border-radius: 16px;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.5s ease;
  }
  .jr-fork-card:hover::after {
    opacity: 1;
  }

  /* EXPLORED card */
  .jr-fork-card.explored {
    border-color: rgba(16,185,129,0.12);
  }
  .jr-fork-card.explored::before {
    background: linear-gradient(90deg, #10B981, #34D399);
  }
  .jr-fork-card.explored::after {
    background: radial-gradient(ellipse at 30% 20%, rgba(16,185,129,0.06) 0%, transparent 70%);
  }
  .jr-fork-card.explored:hover {
    border-color: rgba(16,185,129,0.25);
    box-shadow:
      0 8px 32px rgba(16,185,129,0.06),
      0 0 0 1px rgba(16,185,129,0.08) inset;
    transform: translateY(-2px) scale(1);
  }

  /* CHOSEN card */
  .jr-fork-card.chosen {
    border-color: rgba(124,58,237,0.15);
  }
  .jr-fork-card.chosen::before {
    background: linear-gradient(90deg, #7C3AED, #A78BFA);
  }
  .jr-fork-card.chosen::after {
    background: radial-gradient(ellipse at 30% 20%, rgba(124,58,237,0.06) 0%, transparent 70%);
  }
  .jr-fork-card.chosen:hover {
    border-color: rgba(124,58,237,0.3);
    box-shadow:
      0 8px 32px rgba(124,58,237,0.08),
      0 0 0 1px rgba(124,58,237,0.08) inset;
    transform: translateY(-2px) scale(1);
  }

  /* Tags */
  .jr-fork-tag {
    display: inline-flex; align-items: center; gap: 5px;
    padding: 4px 11px; border-radius: 999px;
    font-size: 0.6rem; font-weight: 700;
    letter-spacing: 0.1em; text-transform: uppercase;
    margin-bottom: 14px;
  }
  .jr-fork-tag.explored {
    background: rgba(16,185,129,0.08); color: #6EE7B7;
    border: 1px solid rgba(16,185,129,0.15);
  }
  .jr-fork-tag.chosen {
    background: rgba(124,58,237,0.08); color: #C4B5FD;
    border: 1px solid rgba(124,58,237,0.15);
  }

  .jr-fork-emoji {
    font-size: 1.8rem; margin-bottom: 10px; display: block;
    filter: drop-shadow(0 2px 8px rgba(0,0,0,0.3));
  }
  .jr-fork-title {
    font-family: var(--heading-font);
    font-size: 0.95rem; font-weight: 700; color: var(--pearl);
    margin-bottom: 6px; letter-spacing: -0.01em;
  }
  .jr-fork-desc {
    font-size: 0.76rem; color: rgba(148,163,184,0.75); line-height: 1.65;
    margin-bottom: 16px;
  }

  /* Achievement items */
  .jr-ach-list {
    display: flex; flex-direction: column; gap: 7px;
  }
  .jr-ach-item {
    display: flex; align-items: center; gap: 10px;
    padding: 9px 13px; border-radius: 10px;
    background: rgba(255,255,255,0.015);
    border: 1px solid rgba(255,255,255,0.035);
    font-size: 0.74rem; color: rgba(148,163,184,0.8);
    transition: all 0.4s cubic-bezier(0.22,1,0.36,1);
    opacity: 0;
    transform: translateX(-8px);
    letter-spacing: 0.01em;
  }
  .jr-ach-item.active {
    opacity: 1;
    transform: translateX(0);
  }
  .jr-ach-item:hover {
    background: rgba(255,255,255,0.03);
    border-color: rgba(255,255,255,0.07);
    color: var(--pearl);
  }
  .jr-ach-check {
    width: 20px; height: 20px; border-radius: 6px;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.6rem; flex-shrink: 0;
    transition: all 0.4s ease;
  }
  .jr-ach-check.done {
    background: rgba(16,185,129,0.12); color: #6EE7B7;
    border: 1px solid rgba(16,185,129,0.2);
    box-shadow: 0 0 8px rgba(16,185,129,0.1);
  }
  .jr-ach-check.pending {
    background: rgba(255,255,255,0.03); color: var(--faint);
    border: 1px solid rgba(255,255,255,0.05);
  }

  /* Divider */
  .jr-fork-divider {
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    gap: 4px; position: relative;
  }
  .jr-fork-divider-line {
    width: 1px; flex: 1;
    background: linear-gradient(to bottom,
      transparent,
      rgba(255,255,255,0.06),
      transparent
    );
  }
  .jr-fork-or {
    font-family: var(--mono-font);
    font-size: 0.58rem; font-weight: 600;
    color: rgba(100,116,139,0.5); letter-spacing: 0.1em;
    padding: 8px 0;
  }

  /* ── Outcome row ── */
  .jr-outcome {
    display: grid; grid-template-columns: repeat(4, 1fr);
    gap: 10px;
  }
  @media (max-width: 500px) {
    .jr-outcome { grid-template-columns: repeat(2, 1fr); }
  }
  .jr-outcome-card {
    padding: 18px 12px;
    border-radius: 14px;
    border: 1px solid rgba(255,255,255,0.05);
    background: rgba(255,255,255,0.02);
    text-align: center;
    transition: all 0.5s cubic-bezier(0.22,1,0.36,1);
    opacity: 0; transform: translateY(10px);
    position: relative;
    overflow: hidden;
  }
  .jr-outcome-card::after {
    content: '';
    position: absolute; inset: 0;
    border-radius: 14px;
    background: radial-gradient(circle at 50% 0%, var(--glow-color, rgba(255,255,255,0.03)) 0%, transparent 70%);
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.4s ease;
  }
  .jr-outcome-card:hover::after { opacity: 1; }
  .jr-outcome-card.active {
    opacity: 1; transform: translateY(0);
  }
  .jr-outcome-card:hover {
    transform: translateY(-3px);
    border-color: rgba(255,255,255,0.1);
    box-shadow: 0 12px 32px rgba(0,0,0,0.2);
  }
  .jr-outcome-num {
    font-family: var(--heading-font);
    font-size: 1.5rem; font-weight: 800;
    line-height: 1;
    margin-bottom: 6px;
  }
  .jr-outcome-lbl {
    font-size: 0.66rem; color: rgba(148,163,184,0.6);
    font-weight: 500; letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  /* ── Quote ── */
  .jr-quote {
    position: relative;
    padding: 22px 28px;
    border-radius: 14px;
    margin: 4px 0 0;
    opacity: 0; transform: translateY(8px);
    transition: all 0.8s cubic-bezier(0.22,1,0.36,1) 0.4s;
    background: linear-gradient(135deg, rgba(245,158,11,0.04) 0%, rgba(124,58,237,0.02) 100%);
    border: 1px solid rgba(245,158,11,0.1);
    overflow: hidden;
  }
  .jr-quote::before {
    content: '"';
    position: absolute; top: 8px; left: 16px;
    font-family: var(--heading-font);
    font-size: 4rem; font-weight: 900;
    color: rgba(245,158,11,0.08);
    line-height: 1; pointer-events: none;
  }
  .jr-quote::after {
    content: '';
    position: absolute; top: 0; left: 0; bottom: 0;
    width: 3px;
    background: linear-gradient(to bottom, #F59E0B, rgba(245,158,11,0.2));
    border-radius: 3px 0 0 3px;
  }
  .jr-quote.active {
    opacity: 1; transform: translateY(0);
  }
  .jr-quote-text {
    position: relative;
    font-size: 0.86rem; color: rgba(241,245,249,0.85);
    font-style: italic; line-height: 1.75;
    font-weight: 400;
  }
  .jr-quote-text strong {
    color: #FCD34D; font-weight: 600; font-style: normal;
  }
  .jr-quote-attr {
    font-size: 0.72rem; color: var(--faint);
    margin-top: 8px; font-style: normal;
  }

  /* ── Header ── */
  .jr-header {
    display: flex; align-items: center; justify-content: space-between;
    gap: 12px; flex-wrap: wrap;
    padding: 28px 32px 0;
    margin-bottom: 0;
  }
  .jr-header-left {
    display: flex; align-items: center; gap: 14px;
  }
  .jr-header-icon {
    width: 52px; height: 52px; border-radius: 16px;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.5rem;
    background: linear-gradient(135deg, rgba(245,158,11,0.1), rgba(124,58,237,0.06));
    border: 1px solid rgba(245,158,11,0.12);
    position: relative;
    box-shadow:
      0 0 20px rgba(245,158,11,0.06),
      0 0 0 1px rgba(245,158,11,0.04) inset;
  }
  .jr-header-title {
    font-family: var(--heading-font);
    font-size: 1.2rem; font-weight: 800;
    color: var(--pearl);
    letter-spacing: -0.02em;
  }
  .jr-header-sub {
    font-size: 0.76rem; color: rgba(148,163,184,0.6); margin-top: 3px;
    font-style: italic;
  }
  .jr-period {
    display: inline-flex; align-items: center; gap: 7px;
    padding: 7px 16px; border-radius: 999px;
    font-family: var(--mono-font);
    font-size: 0.7rem; font-weight: 600;
    color: rgba(252,211,77,0.85);
    background: rgba(245,158,11,0.05);
    border: 1px solid rgba(245,158,11,0.12);
    letter-spacing: 0.03em;
  }

  /* ── Progress bar ── */
  .jr-progress-bar {
    margin: 0 32px;
    padding: 18px 0 8px;
  }
  .jr-progress-track {
    height: 2px; border-radius: 999px;
    background: rgba(255,255,255,0.03);
    overflow: hidden;
  }
  .jr-progress-fill {
