  }
`;

const CHAPTERS = [
  {
    num: '01',
    numColor: '#06B6D4',
    title: 'The Crossroads',
    subtitle: 'After 3 years at TCS, I stood at a crossroads. Instead of staying safe in the corporate lane, I chose to explore — because I wanted to know what I was truly capable of.',
  },
  {
    num: '02',
    numColor: '#F59E0B',
    title: 'Two Roads Diverged',
    subtitle: null, // fork visual
    fork: {
      left: {
        tag: 'Explored',
        emoji: '🏛️',
        title: 'Government & Teaching',
        desc: 'Prepared rigorously for competitive exams to pursue a career in public service and academia.',
        achievements: [
          { text: 'CGPSC Lecturer exam — Cleared', done: true },
          { text: 'Reached final interview round', done: true },
          { text: 'Placed on official waiting list', done: true },
        ],
      },
      right: {
        tag: 'Chosen',
        emoji: '💻',
        title: 'Higher Education in Tech',
        desc: 'Simultaneously prepared for GATE to pursue M.Tech at a premier NIT.',
        achievements: [
          { text: 'GATE 2015 — Qualified', done: true },
          { text: 'GATE 2016 — Qualified', done: true },
          { text: 'GATE 2017 — Qualified & Admitted', done: true },
        ],
      },
    },
  },
  {
    num: '03',
    numColor: '#10B981',
    title: 'The Deliberate Pivot',
    subtitle: null, // outcomes + quote
    outcomes: [
      { num: '3×', label: 'GATE Qualified', color: '#A78BFA' },
      { num: '1', label: 'Govt. Exam Cleared', color: '#34D399' },
      { num: 'NIT', label: 'M.Tech Secured', color: '#67E8F9' },
      { num: '3yr', label: 'Of Deep Focus', color: '#FCD34D' },
    ],
    quote: {
      text: 'I proved I could succeed on the government path — then <strong>deliberately chose tech</strong> because building software is where my passion lives. These years weren\'t a gap; they were the period I figured out <strong>what I truly wanted</strong>.',
    },
  },
];

const JourneyRoadmap = () => {
  const [visible, setVisible] = useState(false);
  const [step, setStep] = useState(0); // which chapter is active
  const [achStep, setAchStep] = useState(0); // achievements reveal
  const rootRef = useRef(null);

  // Trigger on scroll into view
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          io.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  // Sequence chapters
  useEffect(() => {
    if (!visible) return;
    let s = 0;
    const t = setInterval(() => {
      s++;
      setStep(s);
      if (s >= CHAPTERS.length) clearInterval(t);
    }, 600);
    return () => clearInterval(t);
  }, [visible]);

  // Sequence achievements (after chapter 2 appears at step >= 2)
  useEffect(() => {
    if (step < 2) return;
    let a = 0;
    const t = setInterval(() => {
      a++;
      setAchStep(a);
      if (a >= 6) clearInterval(t);
    }, 200);
    return () => clearInterval(t);
  }, [step]);

  const progress = visible ? Math.min(step / CHAPTERS.length, 1) : 0;

  return (
    <>
      <style>{STYLES}</style>
      <div ref={rootRef} className="jr-root">

        {/* Header */}
        <div className="jr-header">
          <div className="jr-header-left">
            <div className="jr-header-icon">🏆</div>
            <div>
              <div className="jr-header-title">The Roads I Took</div>
              <div className="jr-header-sub">A story of exploration, not a gap</div>
            </div>
          </div>
          <div className="jr-period">
            <span style={{ color: '#10B981', fontSize: '0.55rem' }}>●</span>
            2014 → 2017
          </div>
        </div>

        {/* Progress bar */}
        <div className="jr-progress-bar">
          <div className="jr-progress-track">
            <div className="jr-progress-fill" style={{ width: `${progress * 100}%` }} />
          </div>
          <div className="jr-progress-labels">
            <span className="jr-progress-label">left TCS</span>
            <span className="jr-progress-label">joined MNNIT</span>
          </div>
        </div>

        {/* ── Chapter 1: The Crossroads ── */}
        <div className={`jr-chapter${step >= 1 ? ' active' : ''}`}>
          <div className="jr-ch-num">
            <span className="jr-ch-num-dot" style={{ background: CHAPTERS[0].numColor }} />
            Chapter {CHAPTERS[0].num}
          </div>
          <div className="jr-ch-title">{CHAPTERS[0].title}</div>
          <div className="jr-ch-subtitle">{CHAPTERS[0].subtitle}</div>
        </div>

        {/* ── Chapter 2: Fork in the road ── */}
        <div className={`jr-chapter${step >= 2 ? ' active' : ''}`}>
          <div className="jr-ch-num">
            <span className="jr-ch-num-dot" style={{ background: CHAPTERS[1].numColor }} />
            Chapter {CHAPTERS[1].num}
          </div>
          <div className="jr-ch-title">{CHAPTERS[1].title}</div>
          <div className="jr-ch-subtitle" style={{ marginBottom: 20 }}>
            I didn't pick one road — I walked both simultaneously.
          </div>

          <div className="jr-fork-wrap">
            {/* LEFT: Government path */}
            <div className={`jr-fork-card explored${step >= 2 ? ' active' : ''}`}
              style={{ transitionDelay: '0.2s' }}>
              <div className="jr-fork-tag explored">✓ Explored</div>
              <span className="jr-fork-emoji">{CHAPTERS[1].fork.left.emoji}</span>
              <div className="jr-fork-title">{CHAPTERS[1].fork.left.title}</div>
              <div className="jr-fork-desc">{CHAPTERS[1].fork.left.desc}</div>
              <div className="jr-ach-list">
                {CHAPTERS[1].fork.left.achievements.map((a, i) => (
                  <div
                    key={i}
                    className={`jr-ach-item${achStep > i ? ' active' : ''}`}
                    style={{ transitionDelay: `${i * 0.15}s` }}
                  >
                    <span className={`jr-ach-check ${a.done ? 'done' : 'pending'}`}>
                      {a.done ? '✓' : '·'}
                    </span>
                    {a.text}
                  </div>
                ))}
              </div>
            </div>

            {/* Divider */}
            <div className="jr-fork-divider">
              <div className="jr-fork-divider-line" />
              <span className="jr-fork-or">AND</span>
              <div className="jr-fork-divider-line" />
            </div>

            {/* RIGHT: Tech path */}
            <div className={`jr-fork-card chosen${step >= 2 ? ' active' : ''}`}
              style={{ transitionDelay: '0.5s' }}>
              <div className="jr-fork-tag chosen">★ Chosen</div>
              <span className="jr-fork-emoji">{CHAPTERS[1].fork.right.emoji}</span>
              <div className="jr-fork-title">{CHAPTERS[1].fork.right.title}</div>
              <div className="jr-fork-desc">{CHAPTERS[1].fork.right.desc}</div>
              <div className="jr-ach-list">
                {CHAPTERS[1].fork.right.achievements.map((a, i) => (
                  <div
                    key={i}
                    className={`jr-ach-item${achStep > i + 3 ? ' active' : ''}`}
                    style={{ transitionDelay: `${i * 0.15}s` }}
                  >
                    <span className={`jr-ach-check ${a.done ? 'done' : 'pending'}`}>
                      {a.done ? '✓' : '·'}
                    </span>
                    {a.text}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* ── Chapter 3: The Deliberate Pivot ── */}
        <div className={`jr-chapter${step >= 3 ? ' active' : ''}`}>
          <div className="jr-ch-num">
            <span className="jr-ch-num-dot" style={{ background: CHAPTERS[2].numColor }} />
            Chapter {CHAPTERS[2].num}
          </div>
          <div className="jr-ch-title">{CHAPTERS[2].title}</div>

          {/* Outcome numbers */}
          <div className="jr-outcome" style={{ marginBottom: 20 }}>
            {CHAPTERS[2].outcomes.map((o, i) => (
              <div
                key={i}
                className={`jr-outcome-card${step >= 3 ? ' active' : ''}`}
                style={{ transitionDelay: `${0.2 + i * 0.15}s` }}
              >
                <div className="jr-outcome-num" style={{ color: o.color }}>{o.num}</div>
                <div className="jr-outcome-lbl">{o.label}</div>
              </div>
            ))}
          </div>

          {/* Reflection quote */}
          <div className={`jr-quote${step >= 3 ? ' active' : ''}`}>
            <div
              className="jr-quote-text"
              dangerouslySetInnerHTML={{ __html: CHAPTERS[2].quote.text }}
            />
          </div>
        </div>

      </div>
    </>
  );
};

export default JourneyRoadmap;
